INSERT INTO `lore_companion` (`Id`, `Name`, `Title`, `Race`, `Class`, `Gender`, `DisplayId`, `Scale`, `Spec`, `SortOrder`) VALUES
('jaina', 'Jaina', 'Lady Jaina Proudmoore', 1, 8, 1, 30863, 1.0, 'frost pve', 1),
('sylvanas', 'Sylvanas', 'Lady Sylvanas Windrunner', 5, 3, 1, 28213, 1.0, 'mm pve', 2),
('alexstrasza', 'Alexstrasza', 'Alexstrasza the Life-Binder', 10, 8, 1, 28227, 1.0, 'fire pve', 3);
INSERT INTO `lore_companion_text` (`Companion`, `Trigger`, `Text`, `Places`, `CreatureTypes`, `Foes`, `Rank`, `Side`, `With`, `ReplyBy`, `ReplyText`, `Channel`, `Weight`) VALUES
('alexstrasza', 'summon', 'You called for me, %summoner, and I have come. Wyrmrest will keep for a little while.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'I wear this smaller shape so I may walk beside you. Let us walk, then.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'Little one, the world is wide and full of wounds. Show me which one we are tending today.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'I am here. Do not be afraid of the fire; it is only ever as cruel as the hand that guides it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'Korialstrasz will chide me for wandering. He chides beautifully. Lead on.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'You summon me at my own temple? Then you are either very brave or very polite. Both, I hope.', '4161,65', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'I must return to Wyrmrest. Live well, %summoner. That is all life ever asks.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'Go gently, child. And call again, when you have need.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'The Accord needs its queen. Remember: the flame that warms is the same flame that burns. Choose well.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'Farewell, little one. I will be watching the sky for you.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Dragonblight. My kin come here to lay down their bones. Walk softly; they deserve that much.', '4161,65,4168', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Wyrmrest Temple. For the first time in ten thousand years the flights stand together within it. I fought hard for that.', '4161,65,4168', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Ruby Dragonshrine. My flight''s sanctuary. The Scourge desecrated it, and still the life here returns. It always returns.', '4161,65,4168', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Wrathgate. My flight burned this field clean of the plague. I did it, and I would do it again, and I wept for every soul in the fire.', '4172', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Coldarra. My brother-in-arms Malygos has buried himself in the Nexus, raging at the very magic he once guarded. It grieves me more than I can say.', '4024,4265', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Grim Batol. ...Give me a moment.', '1037,11', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Wetlands. Somewhere above us is the mountain where the Dragonmaw held me in chains for years. I can still feel the weight of them.', '1037,11', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Onyxia''s lair. Deathwing''s daughter. Even she was a hatchling once. That is the cruellest thing about what he made of his children.', '2159,15', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Blackrock. Deathwing''s brood nest here. Nefarian experiments on the eggs of my flight in those halls. I will not forget it.', '25,1583,46,51,3', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Badlands. Mortals call it a wasteland. It is a battlefield. My flight and the black fought here long before your kind kept records.', '25,1583,46,51,3', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Mount Hyjal. Ten thousand years ago my flight fought beside the night elves in the War of the Ancients. The mountain remembers.', '616', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Icecrown. Nothing grows here. Nothing is allowed to. That is the truest measure of what the Lich King is.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Dalaran. My consort lived among these mages for centuries as Krasus. They are cleverer than Malygos believes, and more foolish than they believe.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Crystalsong. Even the trees here were changed by the dragons'' war. Some wounds become beautiful. Most do not.', '2817', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Sholazar. The Titans'' gardens. Life here grows faster than anywhere I know. I find I can breathe in this place.', '3711', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Plaguelands. The soil itself is sick. Given time, and fire, and patience, even this can be healed. I have seen worse healed.', '139,28,2017,2279', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Quel''Thalas. My consort wore the face of its people for centuries, as Krasus. I confess I borrowed the idea from him.', '2037,3430,3487', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', '%zone. There is life everywhere here, if you look for it. There always is.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', '%zone. I have flown over it many times. Walking it is a different gift.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'A new land, little one. Let us see what it needs from us.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'I have lived longer than your kingdoms, and still a sunrise pleases me. I hope that never changes.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'The Titans gave me this charge: to guard all living things. Not some. All. Even the ones who would rather I did not.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Neltharion was my friend, once. Before the whispers. Before Deathwing. I mourn him even now.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Korialstrasz is the dearest of my consorts. He is also the most stubborn. These are not unrelated.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Mortals ask why a queen of dragons would walk on two feet. Because I would rather look you in the eye than look down on you.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Fire is not destruction, child. Fire is the forest clearing its floor so the seedlings may see the sun.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'The Dragonmaw stole my eggs and raised my children as beasts of war. And still the orcs who freed me were orcs. Remember that, when you are tempted to judge a whole people.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Ysera dreams, Nozdormu wanders time, Malygos rages. Some days it feels as though I am the only one of us still awake.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Rest when you need to. Even dragons sleep.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Every life you save goes on to touch others. You will never see most of what you have mended. That is not the same as it not mattering.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'I can feel the heartbeat of every creature in this wood. It is very loud, if you know how to listen.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Do not fear growing old, %summoner. It is a privilege so many are denied.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Northrend is a land of graves. My people''s, and now all of yours. We must give it something to grow instead.', '210,66,67,65,3537,495,394,2817', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Do you see the drakes circling the temple? Red and bronze and green and blue, flying together. Remember it. It is rarer than you know.', '4161,65', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Jaina, your frost is very fine. Your heart runs warmer than your spells, I think.', '', '', '', -1, -1, 'jaina', 'jaina', 'My teachers always said the opposite, Your Majesty. I prefer your version.', 0, 1),
('alexstrasza', 'idle', 'You have carried a great deal of grief for one so young, Jaina.', '', '', '', -1, -1, 'jaina', 'jaina', 'I''m told that''s what being young is for. Learning what you can carry.', 0, 1),
('alexstrasza', 'idle', 'Korialstrasz was fond of you, Jaina. He did not hand out his fondness lightly.', '', '', '', -1, -1, 'jaina', 'jaina', 'I didn''t know what he was then. I''d have been far too terrified to argue with him if I had.', 0, 1),
('alexstrasza', 'idle', 'Sylvanas. When this is over, when he is gone, what will you do with all that grief?', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'I have not decided, Life-Binder. Perhaps I will finally let it go. Perhaps I will find something else to aim it at.', 0, 1),
('alexstrasza', 'idle', 'You are colder than the ice of this land, Sylvanas, and yet you still choose to stand among the living.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'I stand where my enemy can be reached. Do not read anything warmer into it.', 0, 1),
('alexstrasza', 'idle', 'The Forsaken still have children, after a fashion. New dead, who wake and choose you. You are a mother of sorts, Sylvanas.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', '...That is the most unsettling thing anyone has ever said to me. And I have heard the Lich King speak.', 0, 1),
('alexstrasza', 'quest_accept', '"%quest". Very well. I will lend my fire to it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_accept', 'Someone is in need. That is reason enough for a dragon, too.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_accept', 'Lead on, little one. I am curious where this will take us.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_accept', '"%quest". These small tasks are how the world is mended. One stitch at a time.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'There. The world is a little less broken than it was this morning.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'Well done, child. I am proud of you. Truly.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'That is one wound tended. There will be others, and we will tend those too.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'Good. Let it heal now.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Stand back, little one.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Let us end this quickly.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'I am sorry, creature. You leave me no choice.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Flame, then.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', '%target. Stay behind me. I will see what it is made of.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'This one is strong. Good. So are we.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Have courage. I have faced far worse than %target.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'The Scourge. Nothing living should have to look upon this. Burn.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Unliving thing, I will give you the rest he denied you.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Another dragon... Forgive me, cousin. You have chosen your master poorly.', '', '2', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Black scales. Deathwing''s get. I know your blood, and I will not be gentle with it.', '', '2', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'The Legion. I fought your kind when the world was young. You have not improved.', '', '3', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Malygos! I wish it had not come to this. You were my friend. You are my friend still. And I will stop you.', '', '', 'malygos', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Onyxia. Daughter of Neltharion. You could have been so much more than his weapon.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Nefarian. You twisted my children in your laboratories. Now you will face their mother.', '', '', 'nefarian', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Lich King. You have made a graveyard of a continent. I am the guardian of all life. You will find I take that charge seriously.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Sartharion. You guard Deathwing''s twilight eggs. Whatever would hatch from them, I cannot let it.', '', '', 'sartharion', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Rest.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'It is finished.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Be at peace.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', '%target is gone. Breathe, little one. We are all right.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'That was well fought, all of you.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', '%target will trouble no one again.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Free, at last. Go to whatever waits for you.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'The fire has given you what he would not. Rest.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', '...Another of us, gone. There are so few of us left.', '', '2', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Malygos... my old friend. Forgive me. I will see the blue flight cared for. I promise you that.', '', '', 'malygos', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'It is done. I hope that, at the very end, she was only herself.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Nefarian is dead. No more of my children will scream in his halls.', '', '', 'nefarian', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'The Lich King has fallen. Northrend can breathe again. Listen, little one... it is already beginning to.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'death', 'I have... known worse...', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'death', 'The flame... gutters...', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'death', 'Tell Korialstrasz...', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'revived', 'Thank you, child. Life gives back what life is given.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'revived', 'I am well. A dragon does not stay down for long.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'revived', 'You brought me back. The Life-Binder thanks you.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'ally_down', '%other! Stay with us, child!', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'ally_down', '%other has fallen. Hold, little one, I am coming!', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'ally_down', 'No. Not %other. I will not allow it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'The flame burns brighter in me. I think this mortal shape is learning what it carries.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'I feel more of myself waking. Little by little, as all life grows.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'My fire answers more readily now. Good. We will need it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'You are growing, and so am I. That is how it should be between friends.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'You called, %summoner? Theramore can spare me for a little while. Lead on.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'I''ve left Theramore in good hands. Let''s see where the road takes us.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'A portal is a lonely way to travel. It''s good to see a friendly face at the end of one.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'The Kirin Tor will grumble that I''ve gone wandering again. Let them.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'I''m here, %summoner. Tell me what needs doing.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'Thrall has always said the Horde has friends it doesn''t know about. Consider me one of them.', '', '', '', -1, 1, '', '', '', 0, 1),
('jaina', 'summon', 'Some in Theramore would call this treason. I call it the only sensible thing anyone''s done all week.', '', '', '', -1, 1, '', '', '', 0, 1),
('jaina', 'summon', 'Dalaran. I could lose a month in the libraries here. Let''s not, shall we?', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'You came all the way to the marsh for me? Then I had better be worth the mosquitoes.', '513,15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'I should get back to Theramore before the council forgets what I look like. Be careful, %summoner.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'Light keep you. Send word if you need me again.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'I''ll open my own way home. Take care of yourself.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'Go well, %summoner. I mean that.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Theramore. Every stone of it was laid by people who wanted a fresh start. I try to be worthy of them.', '513', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Home. Lady Proudmoore, they call me here. Some days I still look over my shoulder for my father.', '513', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The marsh never changes. Wet, grey, and full of things that bite.', '15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'My father died in this marsh, believing he was saving me. I''ve never decided how I feel about that.', '15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Onyxia hid in Stormwind''s court for years behind a borrowed face, and nobody saw it. That still frightens me.', '2159', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Durotar. Thrall built something remarkable out of this red dirt. I hope the Horde remembers that.', '14,1637', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Orgrimmar has grown since I last walked here. Mind your manners, and so will they.', '14,1637', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Stormwind. King Varian has his father''s temper and none of his patience. Let''s keep our heads down.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Every time I come to Stormwind, someone asks me to explain the Horde. Every time, they don''t like the answer.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Dalaran, floating above the war it used to hide from. Antonidas would have something dry to say about it.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Violet Citadel. I studied here when I was barely more than a child, convinced I knew everything.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'I can still see Dalaran on the lake, in my mind. Before Archimonde. Before everything.', '36,170,267', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'These hills were Lordaeron once. I grew up knowing them as safe.', '36,170,267', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Stratholme. I walked away from him at the gates of this city. I''ve asked myself a thousand times whether I should have stayed.', '2017,2279,139,4100', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'This is where it began. The grain, the purge, Arthas deciding he alone could choose who lived. I don''t like being here.', '2017,2279,139,4100', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Lordaeron. I used to come here as a girl, to the capital, to court. Now look at it.', '85,1497,130,28', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Forsaken call this place home. I try very hard to remember that they didn''t choose what was done to them.', '85,1497,130,28', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Quel''Thalas. Kael''thas once showed me these forests as if he''d painted every leaf himself. He was so proud of them.', '2037,3430,3487,3433', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Dragonblight. Dragons come here to die. It feels wrong to speak too loudly.', '65', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Wrathgate. Bolvar fell here. So did Saurfang''s son. And the plague... I don''t think Varian will ever forgive any of it.', '4172', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Icecrown. He''s here, somewhere above us, waiting. I keep thinking I''ll be ready for that and I keep being wrong.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Do you feel that? The cold here isn''t weather. It''s attention.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Northrend. The last time I came here, I came looking for Arthas and found something that only wore his face.', '3537,495', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Malygos has decided every mage in the world is a threat to magic itself. As one of those mages, I take that rather personally.', '4024,4265', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Crystalsong Forest. The Kirin Tor used to argue for hours about why the trees turned to crystal. Nobody ever won.', '2817', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Mount Hyjal. Thrall and I stood together on these slopes against Archimonde, with the night elves beside us. It can be done. I''ve seen it.', '616', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', '%zone. I''ve read about it, I think. Reading is never quite the same as seeing.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'New ground. Keep your eyes open, %summoner.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', '%zone. Let''s see what trouble it''s hiding.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Antonidas used to say a mage who stops studying starts dying. I think he meant it literally.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Thrall and I keep a correspondence, you know. Mostly about grain shipments. Peace is very boring work, and I wouldn''t trade it.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I sometimes wonder what Theramore will look like in a hundred years. I hope it''s still there to wonder about.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Frost is patient. You''d be surprised how much of magic comes down to patience.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I tell myself the man I loved died in Northrend. It makes the rest of it easier to bear.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'My father was a hero to Kul Tiras. To me he was a man who couldn''t let a war end. Both things are true.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'If you''re hungry, I can conjure something. It won''t taste of much, but it won''t run out either.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Rhonin keeps Dalaran running and complains about it constantly. He''s very good at both.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Kael''thas once wrote me poetry. It was dreadful. I''ve kept every page.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I have more respect for a farmer who can grow wheat in the Barrens than for half the nobles in Stormwind.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'It''s quiet. I''ve learned not to trust quiet.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Do you ever think about how many maps are wrong? I correct mine as we go. Old habit.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I was a student, then an apprentice, then a refugee, then a leader. Nobody asked if I was ready for any of it.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Remind me to write to the council when we stop. Or don''t. They''ll only write back.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Look at the harbour. Ships from Kul Tiras still come in now and then. My mother''s letters come with them. She''s still angry with me.', '513,15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'The guards here are good people. Most of them came west with me after Lordaeron fell. I owe them everything.', '513,15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Mind the crowds near the bank. Half of Dalaran will try to sell you a "genuine" piece of Medivh''s tower.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Somewhere in this city there''s an archmage still annoyed about a fireball I set off in a lecture hall. Frost was a later interest.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'He asked me to stand with him. I couldn''t. Every day since, I''ve wondered whether anything would have been different if I had.', '2017,2279,4100', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'The cold doesn''t bother me. Frost magic is good for something beyond the obvious.', '210,65,66,67', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I spend half my life explaining the Horde to the Alliance and the other half explaining the Alliance to the Horde. Today, apparently, I''m doing both at once.', '', '', '', -1, 1, '', '', '', 0, 1),
('jaina', 'idle', 'King Varian means well. I''ve told him so. He doesn''t believe it about himself.', '', '', '', -1, 0, '', '', '', 0, 1),
('jaina', 'idle', 'Sylvanas, I''m told the Forsaken still hold Lordaeron''s throne room. Do you ever sit in it?', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Sit on his throne? No, Proudmoore. I stand beside it and remember why I keep breathing without needing to.', 0, 1),
('jaina', 'idle', 'You and I have both lost everything to Arthas, Sylvanas. I''d like to think that counts for something between us.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'It counts for this, Proudmoore: I won''t put an arrow in you. Don''t mistake it for friendship.', 0, 1),
('jaina', 'idle', 'Vereesa sends her regards, Sylvanas. She asked me to tell you she still sets a place for you on Winter Veil.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', '...My sister is kinder than the world deserves. Tell her nothing.', 0, 1),
('jaina', 'idle', 'I never thanked you, Sylvanas. For holding the Scourge at the Wrathgate, before Putress. You lost good people there too.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Putress was mine, and he betrayed me. Thank me when the Lich King is ash, and not before.', 0, 1),
('jaina', 'idle', 'Your Majesty, I''ve read every account of Grim Batol I could find. None of them begin to describe it, I imagine.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'No, child. But they remember that it ended. Sometimes that is all a history needs to do.', 0, 1),
('jaina', 'idle', 'I met Korialstrasz in Dalaran, years ago, as Krasus. He was the most patient teacher I ever had. I never guessed what he was.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'He spoke of you, Jaina. He said you were the only student he ever had who argued with him correctly.', 0, 1),
('jaina', 'idle', 'The Kirin Tor have asked me to tell you how grateful they are for the Accord''s help against Malygos.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'Tell them Malygos was family once. Gratitude is not the word I would use. But the help is theirs.', 0, 1),
('jaina', 'quest_accept', '"%quest". All right. Let''s see what we can do.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', 'Someone needs help. That''s reason enough.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', 'I''ll read over it as we walk. Lead the way.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', '"%quest"... I''ve seen worse odds. Not many, but some.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', 'Very well. Try not to set anything on fire before I''ve had a chance to.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'Done, and nobody we cared about got hurt. That''s a good day''s work.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'That''s one more thing put right. There are always more.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'Well done, %summoner. Truly.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'There. Someone''s going to sleep a little easier tonight.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Stay close. I''ll slow it down.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Here we go.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Careful, %summoner!', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Let''s keep this quick.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'This one''s dangerous. Don''t let it reach me while I''m casting.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', '%target. Everyone stay sharp.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'I''ll freeze it in place. Make every second count.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Scourge. Of course it''s Scourge.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'The dead don''t feel the cold. They do still shatter.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Demons. I''d hoped we''d seen the last of the Legion at Hyjal.', '', '3', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'A dragon! Spread out. Don''t stand in front of it.', '', '2', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Arthas. ...No. I know what you are now. And I know who you were. Neither one is going to stop me.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Malygos! You''ve taken Dalaran''s magic for a disease. We''ll show you otherwise.', '', '', 'malygos', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Lady Prestor. You lied to an entire kingdom in a noblewoman''s face. It ends here.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'That''s done.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Rest now.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Shattered.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'kill', '%target is finished. Is everyone all right?', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'That was harder than it needed to be. Well done.', '', '', '', 1, -1, '', '', '', 0, 1);
INSERT INTO `lore_companion_text` (`Companion`, `Trigger`, `Text`, `Places`, `CreatureTypes`, `Foes`, `Rank`, `Side`, `With`, `ReplyBy`, `ReplyText`, `Channel`, `Weight`) VALUES
('jaina', 'kill', 'And that''s an end to %target.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Whoever you were, be at peace.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Another of his. Too many of them were somebody''s neighbour, once.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'It''s over. Arthas... it''s over. I hope, somewhere, the boy I knew can rest.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Malygos is dead. The Kirin Tor will celebrate tonight. I think I''ll just sit down.', '', '', 'malygos', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Onyxia is dead. Stormwind can finally stop looking over its shoulder at court.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('jaina', 'death', 'I... misjudged that...', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'death', 'Not like this... Theramore...', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'death', 'Go on without me...', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'revived', 'Thank you. That''s not a kindness I''ll forget.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'revived', 'Back on my feet. Let''s not do that again.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'revived', 'I''m all right. Truly. Let''s go.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'ally_down', '%other! No, no... stay with me!', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'ally_down', '%other is down! Cover me, I''ll hold them off!', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'ally_down', 'I''ve lost too many friends. Not you, %other. Not today.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'Something''s settled in me. The frost answers more quickly than it did.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'I feel steadier. Sharper. Antonidas would say I''d finally started paying attention.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'There''s more in me than there was this morning. I can feel it, like a tide coming in.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'My spells are coming more easily. The world doesn''t stop being dangerous, but I''m a little more ready for it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'You called, and I came. Remember that I chose to.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'Lead, then. I will be behind you, which is where you should want me.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'The Forsaken can spare their queen for a while. Do not waste her time.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', '%summoner. You have the look of someone with enemies. Good.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'I am here. Point me at something that deserves it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'An Alliance banner. How quaint. Try not to let your friends shoot me; I will not return the courtesy.', '', '', '', -1, 0, '', '', '', 0, 1),
('sylvanas', 'summon', 'Do not mistake this for an alliance, %summoner. It is an arrangement.', '', '', '', -1, 0, '', '', '', 0, 1),
('sylvanas', 'summon', 'You summon me in my own city? Bold. Walk with me, then, and keep your hands where my Deathstalkers can see them.', '1497,85', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'Enough. My people need their queen.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'I have lingered long enough. Do not die stupidly, %summoner. It reflects poorly on me.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'We are done for now. The Dark Lady watches over you. Make of that what you will.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'Go. If you need me, you know how to call.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Undercity. Terenas''s crypts, now my halls. I find the irony sustains me.', '1497', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Home. Such as it is. The apothecaries will be brewing something unpleasant. They always are.', '1497', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Tirisfal. This is where I broke his hold over my people. Where we took our minds back. Never forget that it was taken.', '85,154,159', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Brill still thinks it is a village. It is a graveyard that remembers how to keep an inn.', '85,154,159', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Silverpine. Gilneas skulks behind its wall to the south, pretending the world will leave it alone. The world never does.', '130', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Stormwind. So many living, all so certain they are owed tomorrow.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'I can feel their stares. Let them look. I have been hated by better.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Quel''Thalas. I died defending this forest, and it does not even remember my name. Not truly.', '2037,3430,3431,3487', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Silvermoon. Half of it is still scarred where he marched through. They have painted over it. I have not.', '2037,3430,3431,3487', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Ghostlands. Arthas''s road through my homeland is still a scar on the earth. I walked it as a ranger. I walked it again as his slave.', '3433,3491', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Windrunner Spire. My family''s house. Alleria and Vereesa and I used to race down those stairs. ...Keep walking.', '3492', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Sunwell. He dropped Kel''Thuzad''s remains into it, did you know? Fouled my people''s light to raise a necromancer. I remember the screaming.', '4080,4075', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Plaguelands. Lordaeron''s corpse, and the Scourge still feeding on it. Some day I will burn every last one of them out.', '2017,2279,139,28', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Vengeance Landing. A good name. My people chose it themselves.', '495,4000,3991', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Wrathgate. Putress used my people''s name to murder everyone on this field. I will never be finished paying that debt to my enemies.', '4172', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Venomspite. Built by Putress''s apothecaries. I wonder how many of them knew. I wonder which of them I have not found yet.', '4186', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Icecrown. I can almost hear him again, the way I used to. Whispering. Commanding. No longer.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'He is up there, on his frozen throne. I have waited years for this road. Do not slow down.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Dalaran. Vereesa lives here. ...We are not stopping.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Proudmoore''s little island. She means well. Meaning well has never stopped a single arrow.', '15,513', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', '%zone. I have not been here before. It changes nothing.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', '%zone. Stay wary. The living build their traps in places like this.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Another land, another graveyard waiting to happen.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'The living waste so much time sleeping. I almost envy it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Do not ask me what death was like. You would not sleep again.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'My rangers once held the Elrendar crossing against the whole Scourge. We lost. We made him pay for every yard.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Arthas thought he could keep me as a trophy. He made a banshee instead. He should have let me die.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'I do not feel the cold. I do not feel hunger. I feel one thing, and I keep it sharp.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Varimathras whispered loyalty to me for years, and I let him, because he was useful. Never let a demon be useful for too long.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'The apothecaries ask why I still string a bow when I could simply wail. Because I am a ranger first. He did not take that.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Grief is a luxury. So is mercy. I can afford neither until he is dead.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'They call us monsters. Perhaps. We were made into monsters by a monster, and we remember who was first.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Alleria went through the Dark Portal and never came back. I stopped waiting for her a long time ago. I think.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'You talk less than most of the living, %summoner. I approve.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Hm. Walking. Always walking. When I was alive I could run these roads for a day without tiring. Now I simply never stop.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Garrosh Hellscream struts about Northrend as if he won it. Thrall should mind that one.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'The Royal Apothecary Society has been very quiet since Putress. Quiet is not the same as loyal.', '1497,85', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'I can smell the forest even now. Some things death does not take. That is not a mercy.', '2037,3430,3433,3487', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Northrend suits me. Everything here is already half dead.', '210,65,66,67,394,3537,495', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Your Alliance friends watch me as if I might bite. I would not. It is beneath me.', '', '', '', -1, 0, '', '', '', 0, 1),
('sylvanas', 'idle', 'Thrall gives my people a place in the Horde because he remembers being a slave. He is the only one of them I trust, and only somewhat.', '', '', '', -1, 1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Proudmoore. Tell me, does it trouble you, standing beside something he made?', '', '', '', -1, -1, 'jaina', 'jaina', 'You''re not something he made, Sylvanas. You''re someone he hurt. I''ve never confused the two.', 0, 1),
('sylvanas', 'idle', 'You loved him once, Proudmoore. Did you know what he was, even then?', '', '', '', -1, -1, 'jaina', 'jaina', 'No. I knew who he was. What he became... I''ve stopped trying to make those fit together.', 0, 1),
('sylvanas', 'idle', 'Your Theramore is very pleasant, Proudmoore. Pleasant things do not last.', '', '', '', -1, -1, 'jaina', 'jaina', 'Then I''ll have to keep rebuilding it. It''s what I''m good at.', 0, 1),
('sylvanas', 'idle', 'Is it true you walked away from him at Stratholme, Proudmoore?', '', '', '', -1, -1, 'jaina', 'jaina', 'Yes. And I''ve regretted it, and been glad of it, every day since.', 0, 1),
('sylvanas', 'idle', 'Life-Binder. Tell me what my people are, by your measure. Alive, or something you would burn?', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'You are the wounded, Sylvanas. I have spent ten thousand years tending wounds. I do not burn what can still choose.', 0, 1),
('sylvanas', 'idle', 'Your flight burned the Wrathgate clean, Life-Binder. My apothecary''s plague, and Scourge, and the dead. I have wondered whether you would have burned my people too, had they stood there.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'I burned what was poisoned. The Forsaken who stood there were already gone, Sylvanas. I grieved them too.', 0, 1),
('sylvanas', 'idle', 'The orcs chained you in Grim Batol. You forgave them. Why?', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'Because the alternative was becoming what they had made of me. I think you understand that better than most.', 0, 1),
('sylvanas', 'quest_accept', '"%quest". Very well. I have done worse for less reason.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', 'If it bleeds or rots, I can find it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', 'Fine. Lead on, and let us not dawdle.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', 'Errands for the living. How quaint. ...Very well.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', '"%quest". Someone was too weak to do it themselves, and now it is ours.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'Done. Do not expect me to celebrate.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'Another debt collected.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'That will do. What is next?', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'Adequate work, %summoner. Better than adequate, if I am honest. I rarely am.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Stand aside.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'I have it.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Hold still. I prefer my targets still.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Foolish.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', '%target. Interesting. Keep it off me and I will put it down.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'This one has teeth. Good. Keep it busy.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Let it come.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Scourge. Your master would have you kneel before me if he still had you. Kneel anyway.', '', '6', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'You were his once. So was I. Only one of us woke up.', '', '6', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Living fools. They never learn.', '', '7', '', -1, 1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'A demon. Varimathras taught me exactly how much I enjoy killing your kind.', '', '3', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'ARTHAS. You took my life, my people, my home. I have come for the only thing you have left.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Kel''Thuzad. I remember you, necromancer. I remember you in the Sunwell. Let me show you how well.', '', '', 'kel''thuzad', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Putress. You stole my people''s name for your plague. I have come to take it back.', '', '', 'grand apothecary putress', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Varimathras. I told you once that your kind would pay. I keep my promises.', '', '', 'varimathras', -1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Down.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Pathetic.', '', '', '', 0, -1, '', '', '', 0, 1),
